      optEl.setAttribute("aria-disabled", "true");
      input.disabled = true;

      if (isSelected && isCorrect) {
        optEl.classList.add("correct");
      } else if (isSelected && !isCorrect) {
        optEl.classList.add("incorrect");
      } else if (!isSelected && isCorrect) {
        optEl.classList.add("missed");
      }
    });

    // A question is fully correct only when selections exactly match correct set
    const selectedArr = [...selected].sort().join(",");
    const correctArr = [...q.correct].sort().join(",");
    if (selectedArr === correctArr) totalCorrect++;
  });

  const resultEl = document.getElementById("result");
  resultEl.innerHTML = `
    <strong>${totalCorrect} / ${QUESTIONS.length} correct</strong>
    ${getResultMessage(totalCorrect)}
    <p style="margin-top:.75rem;font-size:.8125rem;color:#6b7280;">
      <span style="display:inline-block;width:.75rem;height:.75rem;border-radius:2px;background:#dcfce7;border:1.5px solid #16a34a;vertical-align:middle;margin-right:.25rem;"></span>Correct&nbsp;&nbsp;
      <span style="display:inline-block;width:.75rem;height:.75rem;border-radius:2px;background:#fee2e2;border:1.5px solid #dc2626;vertical-align:middle;margin-right:.25rem;"></span>Incorrect&nbsp;&nbsp;
      <span style="display:inline-block;width:.75rem;height:.75rem;border-radius:2px;background:#fef9c3;border:1.5px solid #f59e0b;vertical-align:middle;margin-right:.25rem;"></span>Missed
    </p>
  `;
  resultEl.classList.add("visible");
  resultEl.setAttribute("aria-live", "polite");

  const submitBtn = document.querySelector('button[type="submit"]');
  submitBtn.disabled = true;
  submitBtn.textContent = "Submitted";

  resultEl.focus();
  resultEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function getResultMessage(score) {
  if (score === QUESTIONS.length) return "🎉 Perfect score!";
  if (score >= QUESTIONS.length / 2) return "Good effort — review the highlighted answers below.";
  return "Keep practicing — check the highlighted answers to learn more.";
}

document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
