+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --color-bg: #f5f5f7;
+  --color-surface: #ffffff;
+  --color-primary: #2563eb;
+  --color-primary-hover: #1d4ed8;
+  --color-primary-focus-ring: #93c5fd;
+  --color-text: #111827;
+  --color-text-secondary: #6b7280;
+  --color-border: #e5e7eb;
+  --color-border-hover: #d1d5db;
+  --color-check-bg: #2563eb;
+  --color-check-border: #2563eb;
+  --color-help: #6b7280;
+  --color-success-bg: #f0fdf4;
+  --color-success-text: #166534;
+  --color-success-border: #bbf7d0;
+  --radius-sm: 6px;
+  --radius-md: 12px;
+  --radius-lg: 16px;
+  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.04);
+  --shadow-md: 0 4px 16px rgba(0,0,0,.08), 0 2px 6px rgba(0,0,0,.04);
+}
+
+body {
+  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
+  background: var(--color-bg);
+  color: var(--color-text);
+  min-height: 100vh;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  padding: 2.5rem 1rem 4rem;
+  line-height: 1.5;
+}
+
+/* Skip link */
+.skip-link {
+  position: absolute;
+  top: -100%;
+  left: 1rem;
+  background: var(--color-primary);
+  color: #fff;
+  padding: .5rem 1rem;
+  border-radius: var(--radius-sm);
+  font-size: .875rem;
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+  transition: top .15s;
+}
+.skip-link:focus {
+  top: 1rem;
+}
+
+header {
+  width: 100%;
+  max-width: 640px;
+  margin-bottom: 2rem;
+  text-align: center;
+}
+
+header .badge {
+  display: inline-block;
+  background: #eff6ff;
+  color: var(--color-primary);
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  padding: .25rem .75rem;
+  border-radius: 100px;
+  margin-bottom: .75rem;
+}
+
+header h1 {
+  font-size: 1.875rem;
+  font-weight: 800;
+  letter-spacing: -.02em;
+  color: var(--color-text);
+  margin-bottom: .5rem;
+}
+
+header p {
+  font-size: 1rem;
+  color: var(--color-text-secondary);
+}
+
+main {
+  width: 100%;
+  max-width: 640px;
+}
+
+form {
+  display: flex;
+  flex-direction: column;
+  gap: 1.25rem;
+}
+
+/* Question card */
+.form-field {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  padding: 1.75rem;
+  box-shadow: var(--shadow-sm);
+  transition: box-shadow .2s;
+}
+
+.form-field:focus-within {
+  box-shadow: var(--shadow-md);
+}
+
+.form-field fieldset {
+  border: none;
+  padding: 0;
+  min-width: 0;
+}
+
+.question-meta {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-bottom: .75rem;
+}
+
+.question-num {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 1.5rem;
+  height: 1.5rem;
+  background: #eff6ff;
+  color: var(--color-primary);
+  font-size: .75rem;
+  font-weight: 700;
+  border-radius: 50%;
+  flex-shrink: 0;
+}
+
+.form-field legend {
+  font-size: 1.0625rem;
+  font-weight: 600;
+  color: var(--color-text);
+  line-height: 1.4;
+  padding: 0;
+  float: left;
+  width: 100%;
+  margin-bottom: .5rem;
+}
+
+/* Clearfix for legend float */
+.form-field fieldset::after {
+  content: "";
+  display: table;
+  clear: both;
+}
+
+.help-text {
+  font-size: .8125rem;
+  color: var(--color-help);
+  margin-bottom: 1rem;
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+}
+
+.help-text svg {
+  flex-shrink: 0;
+}
+
+.options {
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+}
+
+/* Custom checkbox option */
+.option {
+  display: flex;
+  align-items: center;
+  gap: .75rem;
+  padding: .75rem 1rem;
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-md);
+  cursor: pointer;
