+    options: ["JavaScript", "TypeScript", "COBOL", "Fortran"],
+    correct: new Set(["JavaScript", "TypeScript"]),
+  },
+  {
+    id: "q3",
+    text: "Which of the following are statically typed languages?",
+    options: ["Java", "Go", "Ruby", "Python"],
+    correct: new Set(["Java", "Go"]),
+  },
+];
+
+function getSelections(questionId) {
+  return Array.from(
+    document.querySelectorAll(`input[name="${questionId}"]:checked`)
+  ).map((el) => el.value);
+}
+
+function handleSubmit(e) {
+  e.preventDefault();
+
+  let totalCorrect = 0;
+
+  QUESTIONS.forEach((q) => {
+    const selected = new Set(getSelections(q.id));
+    const options = document.querySelectorAll(`[data-question="${q.id}"] .option`);
+
+    options.forEach((optEl) => {
+      const input = optEl.querySelector("input");
+      const value = input.value;
+      const isSelected = selected.has(value);
+      const isCorrect = q.correct.has(value);
+
+      optEl.setAttribute("aria-disabled", "true");
+      input.disabled = true;
+
+      if (isSelected && isCorrect) {
+        optEl.classList.add("correct");
+      } else if (isSelected && !isCorrect) {
+        optEl.classList.add("incorrect");
+      } else if (!isSelected && isCorrect) {
+        optEl.classList.add("missed");
+      }
+    });
+
+    // A question is fully correct only when selections exactly match correct set
+    const selectedArr = [...selected].sort().join(",");
+    const correctArr = [...q.correct].sort().join(",");
+    if (selectedArr === correctArr) totalCorrect++;
+  });
+
+  const resultEl = document.getElementById("result");
+  resultEl.innerHTML = `
+    <strong>${totalCorrect} / ${QUESTIONS.length} correct</strong>
+    ${getResultMessage(totalCorrect)}
